/*
Day #17/24: Circuit
https://openprocessing.org/sketch/2408849
https://mathober.com/
https://openprocessing.org/curation/87980
*/

let N, NX, NY, S, cells, circuits;
let TX, TY;

function setup() {
	N = ~~random(13, 27);
	S = ~~(max(windowWidth, windowHeight) / N);
	NX = ~~(windowWidth / S);
	NY = ~~(windowHeight / S);
  createCanvas(windowWidth, windowHeight); // createCanvas(S*NX, S*NY); // (S = max(windowWidth, windowHeight)), S
	TX = ~~((S + windowWidth - S*NX) / 2);
	TY = ~~((S + windowHeight - S*NY) / 2);
	describe("grid of lines connecting circuits on a board / conductor tracks");
	background(2, 2, 8);
	frameRate(60);
	strokeJoin(ROUND);
	// console.log(`${NX}, ${NY}, ${S}`);

	NX--, NY--;
	// init grid & conns
	cells = []; // Array(NX*NY);
	for (let i = 0; i < NX*NY; i++) cells[i] = false;
	circuits = [];	
	startCircuit();

  loop();
}

function draw() {
	background(2, 2, 8)
	translate(TX, TY); // translate(S/2, S/2);

	if (circuits.length && random() < 0.4) extendCircuit();
	if (random() < 0.1) reserveCell();
	if (random() < 0.1) startCircuit();

	if (true) { // debug reserved cells
		push();
		stroke(32);
		for (let i = 0; i < cells.length; i++) {
			if (cells[i]) {			
				const x = i % NX;
				const y = ~~(i / NX)
				circle(x*S, y*S, S/16);
			}
		}
		pop();
	}

	for (let c of circuits) {
		drawCircuit(c);
	}

  // // noLoop() removed for animation
}

function p2I(x, y) {
	return y * NX + x;
}

function drawCircuit(c) {
	stroke(c.clr);
	noFill();
	strokeWeight(S/5);
	beginShape();
	for (let p of c.pts) vertex(p.x*S, p.y*S);
	endShape();

	strokeWeight(S/7);
	fill(2, 2, 8)
	circle(c.pts[0].x*S, c.pts[0].y*S, S/3)
	if (c.ngy === 0) circle(c.pts[c.pts.length-1].x*S, c.pts[c.pts.length-1].y*S, S/3)
}

function getFreeCells() {
	let res = [];
	for (let i = 0; i < cells.length; i++) {
		if (!cells[i]) res.push(i);
	}
	return res;
}

function reserveCell() {
	let freeCells = getFreeCells();
	if (freeCells.length > 0) {
		const idx = random(freeCells);
		if (!cells[idx]) { // when not yet blocked
			cells[idx] = true; // block cell
			return true;
		}
	}
	// noLoop() removed for animation
	return false;
}

function startCircuit() {
	var freeCells = getFreeCells();
	if (freeCells.length > 0) {
		var idx = random(freeCells);
		var x = idx % NX;
		var y = ~~(idx / NX);
		// console.log(`${x}, ${y}, ${idx} ${NX}`);
		if (!cells[idx]) {
			cells[idx] = true;
			const clr = random() < 0.1 ? lerpColor(color("darkred"), color("purple"), random()) : lerpColor(color("cyan"), color("navy"), random());
			const ngy = ~~random(1, NY-y); // enrgy: number of possible moves (till end)
			circuits.push({pts: [{x, y}], clr, ngy});
			// console.log(circuits)
			return true;
		}
	}

	return false;
}

function extendCircuit() {
	if (!circuits || circuits.length < 1) return false;

	const result = circuits.filter((c) => c.ngy > 0);
	if (result.length > 0) {
		const circuit = random(result);
		// if (circuit.ngy === 0) continue;

		let lastPt = circuit.pts[circuit.pts.length-1];
		let validPts = [];
		if (lastPt.x > 0 && !cells[p2I(lastPt.x-1, lastPt.y+1)]) validPts.push({x: lastPt.x-1, y: lastPt.y+1});    // 20% left down
		if (lastPt.x < NX-1 && !cells[p2I(lastPt.x+1, lastPt.y+1)]) validPts.push({x: lastPt.x+1, y: lastPt.y+1}); // 20% right down
		if (!cells[p2I(lastPt.x, lastPt.y+1)]) {			
			validPts.push({x: lastPt.x, y: lastPt.y+1});                        // 60% down (3 times)
			validPts.push({x: lastPt.x, y: lastPt.y+1});
			validPts.push({x: lastPt.x, y: lastPt.y+1});
		}
		// console.log(validPts);
		circuit.ngy--;
		if (validPts.length) {			
			const newPt = random(validPts);
			circuit.pts.push(newPt);
			cells[p2I(newPt.x, newPt.y)] = true;
		} else {
			circuit.ngy = 0;
		}
		return true;
	}

	return false;
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
